	["desc.Pawnbroker"] = "Um goblin verde empoleirado numa pilha altíssima de armas, escudos e tesouros.",
	["desc.Conjurer"] = "Um espírito azul e fantasmagórico flutuando sobre um baú de tesouro.",
	["scene.title.necrodancer"] = "Arte de título: Cadência, de tocha erguida e adaga em punho, enfrenta um fantasma azul-claro com uma flecha atravessando a cabeça, num cemitério escuro. Acima deles, o logotipo do jogo entre duas caveiras.",
	["scene.title.amplified"] = "Arte de título de Amplified: Nocturna, de espada na mão, luta contra um mago esqueleto de chapéu roxo cujo cajado estala de raios.",
	["scene.title.synchrony"] = "Arte de título de Synchrony: Klarineta com sua espada longa, Caçador, o fantasma remendado com sua lanterna verde, e Suzu com sua arma de haste, sob o logotipo de Synchrony.",
	["scene.title.halloween"] = "Arte de título de Dia das Bruxas, Doces ou Travessuras: Caçador, o fantasma remendado com sua lanterna verde, e Cadência com uma abóbora de Halloween na cabeça, entre abóboras brilhantes.",
	["scene.title.christmas"] = "Arte de título de Natal, Merry Cryptmas: Cadência de casaco vermelho de Papai Noel com sua pá; atrás dela, um enorme morto-vivo de barba branca e gorro de Papai Noel, fantasmas e um ceifador encapuzado enchem o céu nevado.",
	["scene.zone1"] = "A cripta: chão de terra escura batida e paredes de terra cheias de raízes, ossos e caveiras, algumas de blocos de pedra. Enquanto você tem multiplicador de moedas, o chão pisca em padrão de xadrez a cada batida.",
	["scene.zone2"] = "Chão de pedra verde e verde-azulada coberta de musgo, paredes de terra tomadas por folhas e cogumelinhos laranja, e paredes de paralelepípedos claros.",
	["scene.zone3"] = "Esta profundidade se divide em duas: um lado quente de rocha avermelhada com chão laranja incandescente, e um lado frio de rocha cinza-azulada com chão azul gelado.",
	["scene.zone4"] = "As catacumbas: chão azul-escuro e paredes de tijolo roxo cobertas de esqueletos, caveiras e estandartes.",
	["scene.zone5"] = "Um laboratório: chão roxo-escuro com ladrilhos dourados e ciano, e paredes de tijolo magenta cobertas de canos, fios e maquinário.",
	["scene.boss"] = "Uma arena de chefe: chão de pedra escura e paredes de pedra clara incrustadas de caveiras e ossos.",
	["scene.boss.NECRODANCER"] = "O palco do NecroDancer: uma pista de dança verde ladeada por caixas de som roxas gigantes.",
	["cs.intro.1"] = "Noite num cemitério. Cadência, uma jovem de cabelo loiro, bandana azul e túnica vermelha, sobe entre as lápides com uma tocha e uma pá, e começa a cavar.",
	["cs.intro.2"] = "A pá dela rompe o chão e uma fumaça roxa explode ao redor dela.",
	["cs.intro.3"] = "O chão cede. Ela cai na escuridão, passando por mãos esqueléticas que tentam agarrá-la.",
	["cs.intro.4"] = "Ela se espatifa no chão de pedra de uma cripta, entre ossos, e fica imóvel numa poça de sangue.",
	["cs.intro.5"] = "Uma luz roxa inunda a sala. Um feiticeiro morto-vivo de pele azul, longa barba branca e capa vermelha se agiganta sobre ela: o NecroDancer.",
	["cs.intro.6"] = "Com sua magia, ele arranca o coração do peito dela e o ergue, sorrindo, enquanto o coração brilha.",
	["cs.intro.7"] = "Cadência acorda no chão e se levanta com sua pá, com fumaça roxa saindo do peito.",
	["cs.intro.8"] = "Ela olha para a frente, determinada.",
	["cs.cadence1.1"] = "Uma casa de madeira iluminada por uma vela. A pequena Cadência espia pelo vão de uma porta.",
	["cs.cadence1.2"] = "O pai dela, Dorian, de gorro verde, guarda um mapa e ferramentas num baú.",
	["cs.cadence1.3"] = "A pequena Cadência olha para baixo, triste, ao lado do tio Eli, um homem grande de barba ruiva e chapéu preto.",
	["cs.cadence1.4"] = "Anos depois, Cadência, já adolescente, remexe no velho baú do pai, com uma pá encostada ao lado.",
	["cs.cadence1.5"] = "Ela tira as anotações dele e um mapa, sorrindo.",
	["cs.cadence1.6"] = "O tio Eli observa da porta, de cara fechada, enquanto Cadência desvia o olhar.",
	["cs.cadence1.7"] = "Cadência segura o mapa com força, determinada.",
	["cs.cadence2.1"] = "Um funeral numa colina verde. Pessoas de luto, em vestidos escuros, estão junto a um caixão vermelho coberto de flores. A pequena Cadência canta ao lado dele.",
	["cs.cadence2.2"] = "Atrás dela, o tio Eli aponta um dedo acusador para o pai dela, Dorian.",
	["cs.cadence2.3"] = "Visto de cima, Dorian abre as mãos, suplicando, enquanto Eli se agiganta sobre ele.",
	["cs.cadence2.4"] = "Em close: Dorian desvia o olhar, tenso; o punho de Eli está cerrado.",
	["cs.cadence2.5"] = "Cadência dá as costas para eles e põe a mão no caixão enquanto pétalas vermelhas passam voando.",
	["cs.cadence3.1"] = "Um piquenique ensolarado à beira de um lago. Uma mulher de lenço vermelho na cabeça, Melodia, toca um alaúde enquanto Dorian gira a pequena Cadência no ar. Um cavalo pasta ali perto.",
	["cs.cadence3.2"] = "A pequena Cadência dança e ri; atrás dela, os pais se abraçam.",
	["cs.cadence3.3"] = "Mais tarde, Melodia está doente na cama, com a cabeça enfaixada e manchas escuras no braço. Dorian segura a mão dela.",
	["cs.cadence3.4"] = "Dorian se vira, perturbado, enquanto a pequena Cadência observa da porta.",
	["cs.cadence4.1"] = "Cadência se ajoelha junto a um homem pálido de cabelo ruivo comprido e armadura dourada: o pai dela, Dorian.",
	["cs.cadence4.2"] = "Num salão da cripta de arcos roxos, o NecroDancer abre os braços, com um alaúde dourado numa das mãos.",
	["cs.cadence4.3"] = "Uma chama na outra mão dele se transforma no coração pulsante de Cadência, e ele o ergue para provocá-la.",
	["cs.cadence4.4"] = "Cadência, com sua pá e sua adaga, fica lado a lado com Dorian, que empunha um pesado martelo dourado.",
	["cs.cadence5.1"] = "O NecroDancer jaz derrotado no chão. Dorian, de armadura dourada, segura o alaúde dourado do NecroDancer; atrás dele, Cadência brilha com uma luz roxa.",
	["cs.cadence5.2"] = "Cadência, de pá na mão, encara o pai enquanto ele se afasta com o alaúde.",
	["cs.cadence5.3"] = "Lá fora, sob uma lua verde, Cadência e Dorian saem entre lápides e raízes retorcidas, com Dorian carregando o alaúde.",
	["cs.melody0.1"] = "Noite no cemitério sob uma lua verde. Dorian toca o alaúde dourado sobre um caixão aberto enquanto Cadência se ajoelha ao lado. No caixão jaz uma mulher ruiva: Melodia.",
	["cs.melody0.2"] = "Os olhos de Melodia se abrem de repente num clarão de luz roxa.",
	["cs.melody0.3"] = "Ela se senta no caixão, e Cadência e Dorian sorriem.",
	["cs.melody0.4"] = "Uma visão do NecroDancer derrotado, com fumaça roxa saindo dele.",
	["cs.melody0.5"] = "Em casa, Melodia, de bandana vermelha e vestido verde, pega uma pá e o alaúde dourado.",
	["cs.melody0.6"] = "Erguendo uma tocha, ela desce por um poço de pedra até a cripta enquanto tentáculos verdes saem das paredes.",
	["cs.melody1.1"] = "Um quarto de doente. Melodia está deitada na cama, pálida, com uma rosa vermelha sobre o cobertor. Dorian, de gorro verde, está sentado ao lado dela, segurando sua mão.",
	["cs.melody1.2"] = "Em close: Dorian se inclina sobre ela, de olhos semicerrados e duros, enquanto ela jaz fraca, com a cabeça enfaixada.",
	["cs.melody2.1"] = "Na cozinha de uma casinha de campo, uma mulher de cabelo grisalho com um alaúde dourado, Ária, ergue com carinho o queixo da jovem Melodia.",
	["cs.melody2.2"] = "Mais tarde, a silhueta escura de Ária sai pela porta, enquanto Melodia fica de costas, de cabeça baixa.",
	["cs.melody3.1"] = "Uma aldeia ao entardecer. Ária toca seu alaúde dourado ao lado da cama de um homem doente enquanto a jovem Melodia cuida dele.",
	["cs.melody3.2"] = "Um aldeão com uma tocha grita e aponta para Ária, parada numa porta; outros se juntam com forcados e foices.",
	["cs.melody3.3"] = "Melodia e Ária estão juntas com o alaúde, cercadas pelos forcados da multidão, num clarão de luz roxa.",
	["cs.melody4.1"] = "No salão da cripta, Melodia toca o alaúde dourado sobre o NecroDancer, caído no chão com sua capa vermelha.",
	["cs.melody4.2"] = "Ele se ergue devagar: pele azul, olhos vermelhos, mãos com garras estendidas.",
	["cs.melody4.3"] = "Visto de cima, Melodia continua tocando enquanto o NecroDancer rasteja na direção dela.",
	["cs.melody4.4"] = "Close do rosto rosnante do NecroDancer, com os olhos brilhando em vermelho.",
	["cs.melody4.5"] = "Em close: Melodia dedilha o alaúde com calma e não para nunca.",
	["cs.melody4.6"] = "O NecroDancer se ergue de vez e grita de raiva num clarão de luz roxa.",
	["cs.melody5.1"] = "O NecroDancer cambaleia para trás, em direção a um caixão de pedra aberto.",
	["cs.melody5.2"] = "Um clarão de luz roxa: uma mulher grisalha de vestido roxo crava uma adaga nele pelas costas enquanto Melodia observa.",
	["cs.melody5.3"] = "A capa vermelha dele desaba no chão aos pés da mulher.",
	["cs.melody5.4"] = "Na cripta escura, Melodia se vira para a mulher grisalha, que ainda segura a adaga.",
	["cs.nocturna1.1"] = "Uma cripta cheia de máquinas estranhas. Nocturna, uma vampira de pele azul-clara, cabelo ruivo e asas de morcego, ergue uma tocha ao lado de uma caveira gigante.",
	["cs.nocturna1.2"] = "Um esqueleto jaz caído contra canos e medidores enquanto uma faísca corre por um cabo.",
	["cs.nocturna1.3"] = "Vista de baixo, Nocturna se ergue imponente com a tocha, de asas abertas.",
	["cs.nocturna1.4"] = "Ela voa escada escura abaixo, com a tocha à frente.",
	["cs.nocturna2.1"] = "Nocturna ergue uma tocha numa sala de máquinas e mostradores luminosos, estendendo a mão para a parede.",
	["cs.nocturna2.2"] = "Ela anda por um longo corredor de metal forrado de cabos e luzes.",
	["cs.nocturna2.3"] = "Em close: a mão azul dela toca cabos grossos estalando com eletricidade amarela.",
	["cs.nocturna2.4"] = "Vista de cima, ela segue os cabos luminosos pelo chão.",
	["cs.nocturna2.5"] = "Ela segue voando, de asas abertas, por um túnel iluminado pelo fogo.",
	["cs.nocturna3.1"] = "Um esqueleto de capacete, ligado às máquinas, está sentado e caído entre faíscas amarelas.",
	["cs.nocturna3.2"] = "Em close: Nocturna o examina, nada impressionada.",
	["cs.nocturna3.3"] = "Ela se agacha ao lado do esqueleto e puxa os cabos das costas dele.",
	["cs.nocturna3.4"] = "Ela segura o feixe de cabos com as duas mãos e depois cerra os punhos.",
	["cs.nocturna3.5"] = "Ela segue sozinha por um longo corredor; outro esqueleto ligado a fios pende da parede.",
	["cs.nocturna4.1"] = "Uma lembrança do passado: uma jovem de pele morena e cabelo castanho cacheado grita e estende a mão enquanto um vampiro azul de olhos vermelhos morde o pescoço dela, com uma igreja atrás deles sob um céu roxo.",
	["cs.nocturna4.2"] = "A pele dela fica azul-clara e o cabelo fica ruivo, enquanto o fogo arde atrás dela.",
	["cs.nocturna4.3"] = "Numa floresta de bétulas brancas, Nocturna, já com asas, se agacha sobre um animal caído enquanto olhos vermelhos observam do escuro.",
	["cs.nocturna4.4"] = "Uma figura vampírica alta, de longo cabelo ruivo esvoaçante, rasteja para fora da escuridão em direção a ela.",
	["cs.nocturna4.5"] = "Em close: Nocturna olha para as mãos ensanguentadas e depois as fecha em punhos.",
	["cs.nocturna5.1"] = "Um laboratório de máquinas. Um enorme corpo mecânico roxo jaz sobre uma mesa, com o peito brilhando enquanto faíscas voam.",
	["cs.nocturna5.2"] = "Nocturna, de espada na mão, avança na direção dele.",
	["cs.nocturna5.3"] = "Uma mulher de casaco roxo e óculos de proteção de latão, cabelo loiro desgrenhado e lábios azuis, se vira do trabalho: a Regente.",
	["cs.nocturna5.4"] = "Nocturna aponta a espada para ela através do vapor.",
	["cs.nocturna5.5"] = "A Regente cruza os braços, nada impressionada.",
	["cs.nocturna5.6"] = "Ela olha Nocturna de cima, com um sorriso malicioso.",
	["cs.nocturna5.7"] = "Ela vai até uma máquina e tira dela um alaúde dourado.",
	["cs.nocturna5.8"] = "O alaúde arde com uma luz amarela nas mãos dela.",
	["cs.nocturna5.9"] = "Nocturna ergue a espada.",
	["cs.nocturna5.10"] = "Nocturna salta sobre ela enquanto raios explodem do alaúde.",
	["cs.nocturna6.1"] = "Nocturna está de pé diante da máquina destruída da Regente, com fumaça subindo, de espada na mão.",
	["cs.nocturna6.2"] = "Ela olha para a própria mão aberta.",
	["cs.nocturna6.3"] = "Uma energia vermelha gira ao redor dela. Os olhos dela brilham em vermelho e ela sorri, mostrando as presas.",
	["cs.nocturna6.4"] = "Ela agarra um aparelho dourado estalando de raios, ergue-o com um grito e o esmaga contra um espelho.",
	["cs.nocturna6.5"] = "Ela pega o alaúde dourado e o ergue acima da cabeça, de olhos em chamas.",
	["cs.nocturna6.6"] = "Os olhos dela voltam ao normal. Ela hesita.",
	["cs.nocturna6.7"] = "No espelho rachado, ela vê seu eu humano: uma mulher de pele morena, cabelo castanho cacheado e óculos redondos.",
	["cs.nocturna6.8"] = "Ela abaixa o alaúde e o segura com calma, com os olhos agora dourados.",
	["cs.nocturna6.9"] = "Uma luz desce lá de cima por um poço. A silhueta dela sobe pela luz e desaparece.",
	["cs.introDlc.1"] = "Noite num cemitério sob a lua cheia e um céu roxo. Um rato de olhos rosa brilhantes se esgueira por um galho.",
	["cs.introDlc.2"] = "Folhas voam sobre os túmulos.",
	["cs.introDlc.3"] = "Uma mão escura com garras sai da terra diante de um túmulo, enquanto um vulto de olhos vermelhos está empoleirado acima dela.",
	["cs.introDlc.4"] = "Uma figura encapuzada de olhos vermelhos brilhantes se agiganta no escuro.",
	["cs.introDlc.5"] = "Em close: olhos vermelhos de vampiro e um sorriso malicioso.",
	["cs.introDlc.6"] = "Uma silhueta alada pousa ao lado de um velho túmulo de pedra.",
	["cs.introDlc.7"] = "Nocturna está sob a lua cheia, de mãos na cintura e asas de morcego abertas.",
	["cs.introDlc.8"] = "Ela pisa com força e a laje de pedra do túmulo se despedaça.",
	["cs.introDlc.9"] = "Ela espia o túmulo quebrado, onde uma passagem rosa brilhante leva para baixo.",
	["cs.introDlc.10"] = "Ela mergulha lá dentro, e mãos mortas saem arranhando da terra atrás dela.",
	["cs.aria0.1"] = "Na cripta, Melodia toca o alaúde dourado. Atrás dela está sua mãe, Ária: cabelo grisalho, vestido roxo, armadura de couro marrom e uma adaga na mão.",
	["cs.aria0.2"] = "Em close: Melodia a encara com raiva.",
	["cs.aria0.3"] = "Ária olha para baixo, envergonhada, iluminada pela luz das tochas.",
	["cs.aria0.4"] = "A raiva de Melodia se transforma em tristeza; ela continua tocando.",
	["cs.aria0.5"] = "Ária estende a mão aberta para a filha.",
	["cs.aria1.1"] = "Ária toca o alaúde dourado diante de um arco de pedra e caveiras.",
	["cs.aria1.2"] = "Num santuário escuro e tomado pela vegetação, ela ergue o alaúde ao lado de um pedestal de pedra onde arde uma chama rosa.",
	["cs.aria1.3"] = "O alaúde ganha vida nas mãos dela: o braço do alaúde se enrola como um dragão dourado e ganha garras, enquanto a chama rosa se aviva.",
	["cs.aria2.1"] = "Uma taverna. Um jovem bardo de barba ruiva e camisa azul toca um alaúde num pequeno palco, enquanto os fregueses o ignoram.",
	["cs.aria2.2"] = "Mais tarde, numa floresta escura, o mesmo bardo, com uma mochila e um cajado de caminhada, protege os olhos de um alaúde dourado que brilha sobre uma pedra.",
	["cs.aria3.1"] = "O bardo, Otaviano, toca o alaúde dourado para um exército de monstros: um enorme minotauro vermelho de chifres dourados, uma gosma verde cheia de ossos e esqueletos brandindo espadas.",
	["cs.aria3.2"] = "Muito antes, Ária anda pela cripta vazia com uma pá e uma tocha.",
	["cs.aria3.3"] = "Em close: Otaviano, agora morto-vivo e de pele azul, com longa barba branca e capa vermelha, toca o alaúde com olhos cansados e vazios.",
	["cs.aria3.4"] = "O alaúde escorrega das mãos dele e some na escuridão.",
	["cs.aria4.1"] = "Ária, com uma pá ao lado, toca o alaúde dourado sobre um caixão de pedra aberto onde jaz o NecroDancer.",
	["cs.aria4.2"] = "Mãos azuis agarram a borda do caixão quando ele desperta.",
	["cs.aria4.3"] = "O NecroDancer se levanta e estende a mão para o alaúde enquanto Ária continua tocando.",
	["cs.aria4.4"] = "Num clarão de luz roxa, Ária estende o alaúde e as mãos azuis dele se fecham sobre o instrumento.",
	["cs.aria4.5"] = "Ele arranca o alaúde e empurra Ária para o lado, com os olhos brilhando em vermelho.",
	["cs.aria5.1"] = "No santuário tomado pela vegetação, Ária protege os olhos enquanto raios roxos jorram do pedestal ao redor do alaúde dourado.",
	["cs.aria5.2"] = "Ela bate o alaúde com força no pedestal e feixes de luz roxa explodem.",
	["cs.aria5.3"] = "Raios roxos a envolvem e ela desaba contra a pedra.",
	["cs.aria5.4"] = "Ao pôr do sol, no alto de uma colina, Cadência está diante de uma lápide com o nome Ária gravado.",
	["cs.aria5.5"] = "Melodia e Dorian se juntam a ela, de braços dados, enquanto o sol se põe.",
}
